<?php require_once 'config/db.php';require_once 'includes/auth.php';require_role(['admin','sales']);$rows=$conn->query("SELECT u.*,COUNT(o.id) order_count,COALESCE(SUM(o.total),0) order_total FROM users u LEFT JOIN orders o ON o.customer_id=u.id WHERE u.role='customer' GROUP BY u.id ORDER BY u.name");include 'includes/header.php';?><div class="card"><h2>Customers</h2><table><tr><th>Name</th><th>Email</th><th>Address</th><th>Orders</th><th>Order value</th></tr><?php while($c=$rows->fetch_assoc()):?><tr><td><?=h($c['name'])?></td><td><?=h($c['email'])?></td><td><?=h($c['address'])?></td><td><?=$c['order_count']?></td><td>₹<?=number_format($c['order_total'],2)?></td></tr><?php endwhile;?></table></div><?php include 'includes/footer.php';?>